steps.input:
H,W=17,19
g=[[0]*W for _ in range(H)]
markers=[(3,4),(8,11),(13,6)]
for r,c in markers:
    g[r][c]=3
for r,c in markers:
    # cap, side rails, and outward horizontal beam
    for j in range(c-2,c+3):
        g[r-2][j]=5
    for i in range(r-1,r+2):
        for j in (c-2,c+2):
            g[i][j]=2
    for j in range(W):
        g[r+2][j]=8 if c-2<=j<=c+2 else 2
    g[r][c]=3
assert len(g)==17 and all(len(row)==19 for row in g)
print('{"action":"submit","grid":'+__import__('json').dumps(g,separators=(',',':'))+'}')
